def forward(groups):
    date_part, time_part = groups[0], groups[1]
    dt = datetime.strptime(f'2023-{date_part} {time_part}', '%Y-%m-%d %H:%M:%S.%f')
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': []}

def inverse(record):
    micros = int(record['stored'][0])
    dt = datetime.fromtimestamp(micros / 1000000)
    return dt.strftime('%m-%d %H:%M:%S.%f')[:-3]

